import { copyFile, cp, mkdir, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";
import { origin } from "../src/catalog.mjs";
import { renderSitemap } from "../src/catalog-runtime.mjs";
import { pages } from "../src/site.mjs";

const root = fileURLToPath(new URL("..", import.meta.url));
const client = join(root, "dist/client");
const assets = join(client, "assets");
const server = join(root, "dist/server");

// Remove detail pages generated by earlier static builds.
await Promise.all(["yedek-parcalar", "urun"].map(path => rm(join(client, path), { recursive: true, force: true })));
await cp(join(root, "public"), client, { recursive: true });
await mkdir(server, { recursive: true });
await Promise.all([
  build({
    entryPoints: [join(root, "src/login.jsx"), join(root, "src/admin.jsx")],
    outdir: assets,
    outExtension: { ".js": ".mjs" },
    bundle: true,
    splitting: true,
    minify: true,
    format: "esm",
    jsx: "automatic",
    define: { "process.env.NODE_ENV": '"production"' },
  }),
  ...["styles.css", "menu.mjs", "auth-client.mjs"].map((file) => copyFile(join(root, "src", file), join(assets, file))),
  ...["auth-client.mjs", "catalog.mjs", "catalog-runtime.mjs", "legacy.mjs", "site.mjs"].map((file) => copyFile(join(root, "src", file), join(server, file))),
  ...[...pages].map(async ([path, html]) => {
    const file = join(client, path, path.endsWith("/") ? "index.html" : "");
    await mkdir(dirname(file), { recursive: true });
    await writeFile(file, html);
  }),
  writeFile(join(client, "robots.txt"), `User-agent: *\nAllow: /\nSitemap: ${origin}/sitemap.xml\n`),
  writeFile(join(client, "sitemap.xml"), renderSitemap()),
]);
